    (vs : Fin n → EuclideanSpace ℝ (Fin r)) :
    (∫ z, signingOffDiagonal vs z ∂fairSigns n) = 0

def signingOffDiagonal {n r : ℕ} (vs : Fin n → EuclideanSpace ℝ (Fin r))
    (z : Signs n) : ℝ :=
  ∑ i, ∑ j, if i = j then 0 else sgn (z i) * sgn (z j) * inner ℝ (vs i) (vs j)

